<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),progress=ref(true),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.gtusage-card')})
watch([dataset,state,progress],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const labels=['Plan','Build','Review','Release']
const rows=computed(()=>dataset.value==='A'?[{s:6,e:10,p:50},{s:9,e:14,p:0},{s:13,e:18,p:100},{s:18,e:18,p:null}]:[{s:8,e:12,p:25},{s:12,e:16,p:75},{s:16,e:22,p:50},{s:22,e:22,p:null}])
const x=(h:number)=>70+(h-6)*13
function reset(){dataset.value='A';state.value='ready';selected.value=0;progress.value=true}
</script>
<template>
<section ref="root" class="gtusage-demo" aria-label="Local Gantt example"><p>Synthetic single-day task plan on a fixed 06–22 local-hour axis. Bar length is planned duration, not effort or completion. Release is a zero-duration milestone. No actual date, timezone or resource calendar is bound.</p><div class="gtusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" :aria-pressed="progress" @click="progress=!progress">Show completion</button><button type="button" @click="reset">Reset example</button></div><div class="gtusage-card"><template v-if="state==='ready'"><svg viewBox="0 0 330 255" role="img" aria-label="Task Gantt timeline, planned hours 06 to 22. Release is a point milestone. Completion overlay is separate from planned duration."><template v-for="h in [6,10,14,18,22]" :key="h"><line class="gtusage-grid" :x1="x(h)" :x2="x(h)" y1="30" y2="210"/><text :x="x(h)" y="233" text-anchor="middle">{{ h }}h</text></template><g v-for="(t,i) in rows" :key="labels[i]" class="gtusage-row" :class="{selected:selected===i}"><text x="3" :y="58+45*i">{{ labels[i] }}</text><template v-if="t.e>t.s"><rect class="gtusage-plan" :x="x(t.s)" :y="43+45*i" :width="(t.e-t.s)*13" height="24" rx="3" data-cm="fade"/><rect v-if="progress&&t.p!==null&&t.p>0" class="gtusage-progress" :x="x(t.s)" :y="43+45*i" :width="(t.e-t.s)*13*t.p/100" height="24" rx="3" data-cm="fade"/></template><path v-else class="gtusage-milestone" :d="`M${x(t.s)},${47+45*i} l8,8 l-8,8 l-8,-8 Z`" data-cm="fade"/></g><text x="70" y="18">Planned clock hours</text></svg><div role="group" aria-label="Select task" class="gtusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: {{ rows[selected].s }}:00–{{ rows[selected].e }}:00, {{ rows[selected].e-rows[selected].s }} planned hours; {{ rows[selected].p===null?'milestone, completion not applicable':rows[selected].p+'% reported completion' }}.</p><p class="gtusage-key">Outlined track = planned interval. Solid color = reported completion fraction when shown. Diamond = milestone. Completion is not elapsed time; no today marker, dependencies, conflict detection or scheduling changes are implemented.</p><table class="gtusage-data"><caption>Exact task plan, dataset {{ dataset }}</caption><thead><tr><th scope="col">Task</th><th scope="col">Hours</th><th scope="col">Duration</th><th scope="col">Done</th></tr></thead><tbody><tr v-for="(t,i) in rows" :key="labels[i]"><th scope="row">{{ labels[i] }}</th><td>{{ t.s }}–{{ t.e }}</td><td>{{ t.e-t.s }}h</td><td>{{ t.p===null?'N/A':t.p+'%' }}</td></tr></tbody></table></template><p v-else role="status" class="gtusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Task plan is withheld.':'No task records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>
.gtusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.gtusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.gtusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.gtusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.gtusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.gtusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.gtusage-demo svg{display:block;width:100%;height:auto;max-height:360px;margin:16px 0}.gtusage-demo svg text{fill:var(--vp-c-text-2);font-size:11px}.gtusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 3}.gtusage-row{opacity:.65}.gtusage-row.selected{opacity:1}.gtusage-plan{fill:var(--vp-c-bg-soft);stroke:var(--vp-c-text-1);stroke-width:1.5}.gtusage-progress{fill:var(--vp-c-brand-1);stroke:var(--vp-c-text-1);stroke-width:.7}.gtusage-milestone{fill:var(--vp-c-brand-1);stroke:var(--vp-c-text-1);stroke-width:1.5}.gtusage-choices{display:flex;gap:6px;flex-wrap:wrap}.gtusage-demo button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.gtusage-data{display:table!important;width:100%;font-size:12px}.gtusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.gtusage-data :is(td,th){padding:6px!important}.gtusage-key{font-size:12px;color:var(--vp-c-text-2)}.gtusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}
</style>
